From ee3be3c8eb97b6d56b8266cb02fc976e468641ea Mon Sep 17 00:00:00 2001
From: Tad Hunt <tad@exablox.com>
Date: Wed, 2 Sep 2015 14:23:17 -0700
Subject: [PATCH] fix Apple OSX build issue

Fix build issue introduced by commit 9b0b8c1cbd1d945fb096d6130f18c99ca901e567
"Local variable names shadowed global function names (e.g. read),
this would cause compile errors with gcc 4.4.7."

diff --git a/src/lib/kinetic_socket.c b/src/lib/kinetic_socket.c
index 96ff7d33..a229e7d6 100644
--- a/src/lib/kinetic_socket.c
+++ b/src/lib/kinetic_socket.c
@@ -165,7 +165,7 @@ void KineticSocket_BeginPacket(int fd)
     int on = 1;
     setsockopt(fd, IPPROTO_TCP, TCP_CORK, &on, sizeof(on));
 #else
-    (void)socket;
+    (void)fd;
 #endif
 }

@@ -175,6 +175,6 @@ void KineticSocket_FinishPacket(int fd)
     int off = 0;
     setsockopt(fd, IPPROTO_TCP, TCP_CORK, &off, sizeof(off));
 #else
-    (void)socket;
+    (void)fd;
 #endif
 }
-- 
2.25.1

Code statements:
- (void)socket;
- (void)socket;

Code statements:
```c
-    (void)socket;
+    (void)fd;
```
```c
-    (void)socket;
+    (void)fd;
```

The code statements that lead to the bug are:
```c
void KineticSocket_BeginPacket(int fd)
{
    ...
    (void)socket;
}
```
```c
void KineticSocket_FinishPacket(int fd)
{
    ...
    (void)socket;
}
```
Reason:
The local variable `socket` is shadowing the global function `socket`, causing ambiguity in the code. When the compiler encounters `(void)socket;`, it cannot determine whether to reference the local variable or the global function, leading to compile errors.

The code statements that fix the bug are:
```c
(void)fd;
```
```c
(void)fd;
```
Reason:
By replacing `(void)socket;` with `(void)fd;`, the code no longer references the shadowed variable `socket`. This resolves the ambiguity and allows the compiler to correctly identify the intended variable, thus fixing the build issue on OSX with GCC 4.4.7.

